//! Lifeguard Reflector — cache coherence microservice for the Lifeguard ORM.
//!
//! A standalone service that keeps shared Redis cache entries coherent with
//! PostgreSQL for every Lifeguard application sharing that cache:
//!
//! 1. **Leader election** — a single-node Redlock (`SET NX PX`, Lua-CAS
//!    renewal) ensures only one reflector instance works at a time.
//! 2. **LISTEN/NOTIFY** — tables with a `#[notify(channel = "...")]`
//!    Lifeguard attribute install a `pg_notify` trigger (generated by
//!    `lifeguard-migrate`). The reflector LISTENs the configured channels.
//! 3. **Active-set refresh** — on each notification the reflector checks
//!    whether the model key exists in Redis; if it does, the row is
//!    re-read from the primary and the key refreshed (`SETEX`). If the row
//!    no longer exists (DELETE), the key is removed. Keys that were never
//!    cached (or already expired) are ignored.
//!
//! The cache key contract is shared with the ORM and asserted by tests in
//! both crates:
//!
//! ```text
//! lifeguard:model:<table>:<primary-key>
//! ```
//!
//! (see `lifeguard::cache::keys::{model_cache_key, DEFAULT_CACHE_TTL_SECS}`)
//! and the cached value is the `serde_json` serialization of the model,
//! keyed by column name — exactly what `ModelManager::find_by_id` writes.

// Pedantic is opt-in via `-W clippy::pedantic` in CI; allow the group
// crate-wide so `-D warnings` applies to real warnings (same convention as
// the `lifeguard` crate).
#![allow(clippy::pedantic)]

pub mod config;
pub mod leader;
pub mod reflector;

pub use config::ReflectorConfig;
pub use leader::LeaderLock;
pub use reflector::{row_to_json, Reflector, ReflectorState, CACHE_KEY_PREFIX, DEFAULT_TTL_SECS};

use thiserror::Error;

/// Errors surfaced by the reflector service.
#[derive(Debug, Error)]
pub enum ReflectorError {
    /// Invalid or incomplete configuration.
    #[error("config error: {0}")]
    Config(String),
    /// Redis operation failed.
    #[error("redis error: {0}")]
    Redis(#[from] redis::RedisError),
    /// PostgreSQL operation failed.
    #[error("postgres error: {0}")]
    Postgres(#[from] may_postgres::Error),
    /// Filesystem error (e.g. reading the config file).
    #[error("io error: {0}")]
    Io(#[from] std::io::Error),
}
